/**
 * Common type transition patterns
 *
 * Represents P(new_type | old_type) for common type refinements.
 */
export const TYPE_TRANSITIONS: readonly TransitionMatrix[] = [
  {
    from: 'unknown',
    transitions: [
      { to: 'string', probability: 0.28 },
      { to: 'number', probability: 0.22 },
      { to: 'object', probability: 0.18 },
      { to: 'boolean', probability: 0.12 },
      { to: 'Array', probability: 0.08 },
      { to: 'null', probability: 0.06 },
      { to: 'undefined', probability: 0.06 },
    ],
  },
  {
    from: 'any',
    transitions: [
      { to: 'string', probability: 0.25 },
      { to: 'number', probability: 0.2 },
      { to: 'object', probability: 0.2 },
      { to: 'boolean', probability: 0.1 },
      { to: 'Array', probability: 0.1 },
      { to: 'Function', probability: 0.08 },
      { to: 'null', probability: 0.04 },
      { to: 'undefined', probability: 0.03 },
    ],
  },
  {
    from: 'object',
    transitions: [
      { to: 'Record', probability: 0.35 },
      { to: 'Array', probability: 0.25 },
      { to: 'Map', probability: 0.12 },
      { to: 'Set', probability: 0.08 },
      { to: 'Function', probability: 0.1 },
      { to: 'null', probability: 0.1 },
    ],
  },
  {
    from: 'string | number',
    transitions: [
      { to: 'string', probability: 0.55 },
      { to: 'number', probability: 0.45 },
    ],
  },
  {
    from: 'T | null',
    transitions: [
      { to: 'T', probability: 0.72 },
      { to: 'null', probability: 0.28 },
    ],
  },
  {
    from: 'T | undefined',
    transitions: [
      { to: 'T', probability: 0.78 },
      { to: 'undefined', probability: 0.22 },
    ],
  },
];

