/**
 * Context weights for combining multiple indicators
 */
export const CONTEXT_WEIGHTS = {
  /**
   * Weight for identifier-based patterns
   */
  identifier: 0.7,

  /**
   * Weight for parent expression context
   */
  parent: 0.5,

  /**
   * Weight for return type context
   */
  returnType: 0.8,

  /**
   * Weight for parameter type context
   */
  paramType: 0.75,

  /**
   * Weight for usage context (how the variable is used)
   */
  usage: 0.6,

  /**
   * Weight for assignment context
   */
  assignment: 0.85,
} as const;
